INSERT INTO dynasties (id, name, start_year, end_year) VALUES ('song', '宋朝', 960, 1279);
INSERT INTO events (dynasty_id, year, year_end, lng, lat, short, title, detail, impact, category) VALUES
  ('song', 960, 975, 114.35, 34.52, '陈桥兵变', '陈桥兵变 · 北宋建立', '后周大将赵匡胤在陈桥驿被部下黄袍加身，回师汴梁，逼后周恭帝禅位，建立宋朝，定都东京开封府（汴梁），是为宋太祖。', '结束五代十国兵戈相夺的乱局，中原重归一统；开创「重文轻武」的文官政治，为两宋经济文化的空前繁荣奠定根基。', 'era'),
  ('song', 963, 978, 114.35, 34.52, '杯酒释兵权', '杯酒释兵权', '宋太祖赵匡胤通过宴请禁军将领，以厚赏换取兵权，解除石守信等高级将领军权，确立「重文轻武」国策，根除唐末以来藩镇割据之弊。', '以近乎和平的方式解决兵权问题，两宋三百年再无武将跋扈、黄袍加身之祸；「强干弱枝」之策稳固了中央集权，也埋下边防孱弱的隐忧。', 'era'),
  ('song', 979, 994, 112.55, 37.87, '北汉灭亡', '太宗灭北汉 · 结束分裂', '宋太宗赵光义亲征，攻灭北汉，结束五代十国分裂局面，基本统一中原。同年乘胜伐辽，于高梁河之战大败。', '五代十国分裂局面正式终结；宋辽由间接对抗转为正面冲突，高梁河之败使燕云十六州再无收复之望，宋辽攻守之势就此逆转。', 'era'),
  ('song', 1004, 1010, 115, 36.4, '澶州之战', '澶州之战', '辽圣宗、萧太后亲率大军南下，宋真宗在宰相寇准力劝下御驾亲征至澶州。宋军射杀辽将萧挞凛，双方议和。', '宋军以逸待劳重创辽军主力，辽国从此无力大举南侵；御驾亲征提振了军民士气，也为澶渊之盟的签订创造了有利条件。', 'military'),
  ('song', 1005, 1040, 115.2, 36.5, '澶渊之盟', '澶渊之盟', '宋辽订立和约：宋每年向辽输「岁币」银十万两、绢二十万匹，双方约为兄弟之国，各守边界。换来百余年的宋辽和平。', '宋辽维持了约一百二十年的和平，榷场贸易繁盛，边境人民免于兵祸；岁币成为宋朝财政的长期负担，也开了「以钱买和」的先例。', 'military'),
  ('song', 1038, 1060, 106.27, 38.47, '西夏建立', '西夏建国', '党项族首领李元昊称帝，建国号「大夏」（史称西夏），定都兴庆府，与宋、辽形成三足鼎立。', '宋、辽、夏三足鼎立格局形成；宋夏连年交战，边防军费浩繁，财政压力促使仁宗朝掀起庆历新政等一系列改革。', 'military'),
  ('song', 1043, 1045, 114.35, 34.78, '庆历新政', '庆历新政', '范仲淹上《答手诏条陈十事》，在宋仁宗支持下推行「明黜陟、抑侥幸、精贡举」等十项改革，触动权贵利益，一年余即废止。', '北宋第一次系统性改革尝试，虽因守旧势力阻挠而夭折，却为后来的熙宁变法积累了经验与人才；也开启了此后绵延数十年的新旧党争。', 'era'),
  ('song', 1069, 1085, 114.35, 34.78, '熙宁变法', '王安石变法（熙宁变法）', '宋神宗任用王安石为参知政事，推行青苗法、募役法、农田水利法、方田均税法等，意在「富国强兵」。因新旧党争激烈，神宗死后尽废。', '国库收入大增、府兵与边防一度振作；但激化了新旧党争，此后变法与废法反复拉锯近五十年，成为北宋中后期政局动荡的总根源。', 'era'),
  ('song', 1084, 1098, 114.35, 34.78, '资治通鉴成书', '《资治通鉴》成书', '司马光主编的编年体通史《资治通鉴》历时十九年完成，共 294 卷，上起周威烈王二十三年（前403），下至后周世宗显德六年（959）。', '与《史记》并称的史学双璧，为后世治史者必读；「鉴于往事，有资于治道」，自此成为历代帝王与士大夫的治政教科书。', 'invention'),
  ('song', 1100, 1125, 114.35, 34.78, '徽宗即位', '宋徽宗即位', '赵佶即位为宋徽宗，任用蔡京、童贯等人，大肆搜刮，营建艮岳，政治日趋腐败，文化艺术却登峰造极，开创「瘦金体」「宣和画院」。', '重用「六贼」使政治腐败达于极点，军备废弛；但徽宗书画造诣冠绝古今，「瘦金体」与宣和画院泽被后世，成为宋代艺术巅峰的象征。', 'era'),
  ('song', 1115, 1125, 126.57, 45.55, '金朝建立', '金朝建立', '女真族完颜阿骨打称帝，国号「金」，定都会宁府（今黑龙江阿城）。金迅速崛起，成为宋辽之间新兴强权。', '女真崛起彻底改变了东北亚力量格局；金朝以「女真不满万，满万不可敌」的兵锋迅速吞辽灭宋，成为此后百余年东亚的主宰。', 'military'),
  ('song', 1120, 1125, 114.35, 34.78, '海上之盟', '海上之盟', '宋徽宗遣使渡海与金相约夹攻辽朝，约定灭辽后宋取燕云十六州，并把原给辽的岁币转给金。埋下北宋灭亡祸根。', '联金灭辽的战略暴露了北宋边防的空虚；金军借道南下如入无人之境，「引狼入室」直接酿成靖康之变。', 'military'),
  ('song', 1125, 1130, 116, 40, '金灭辽', '金灭辽', '金军俘辽天祚帝，辽朝灭亡。金随即以宋收留辽降将为借口，分两路大举南下攻宋。', '辽亡则宋失藩屏，金军两路南下直逼汴京；北宋从此暴露在金兵的兵锋之下，灭亡进入倒计时。', 'military'),
  ('song', 1127, 1140, 114.35, 34.78, '靖康之变', '靖康之变 · 北宋灭亡', '金军攻破东京开封，掳走宋徽宗、宋钦宗父子及宗室、百官数千人北去，北宋灭亡。史称「靖康之耻」。', '北宋灭亡，中原政权第一次被北方游牧民族整体倾覆；徽钦二帝北掳成为汉人心中最深的创痛，「靖康耻」激励了此后数代人的抗金意志。', 'military'),
  ('song', 1127, 1142, 118.78, 32.06, '南宋建立', '南宋建立 · 高宗南渡', '宋徽宗第九子赵构在应天府（今商丘）即位，是为宋高宗，后定都临安（今杭州），史称南宋。与金以淮水—大散关为界南北对峙。', '宋室南渡延续赵宋国祚一百五十二年；中国经济文化重心完成向江南的转移，临安成为当时世界上最繁华的城市之一。', 'era'),
  ('song', 1136, 1142, 114, 33, '岳飞北伐', '岳飞北伐', '岳飞率岳家军连克襄阳、郾城，前锋进抵朱仙镇，距开封仅四十五里。高宗连下十二道金牌召还，十年之功废于一旦。', '岳家军兵锋直指汴京，「直捣黄龙」只差一步；十二道金牌召还与莫须有冤狱，使收复中原最终功败垂成，宋金对峙格局就此定格。', 'military'),
  ('song', 1141, 1162, 118.78, 32.06, '绍兴和议', '绍兴和议', '宋高宗、秦桧与金议和：宋向金称臣，岁贡银二十五万两、绢二十五万匹，以淮水中流为界；并赐死岳飞。', '宋金以淮水—大散关为界的南北分治格局正式确立，维持了约七十年；南宋「称臣纳贡」的屈辱地位，也深刻塑造了此后士人的忧患意识。', 'military'),
  ('song', 1162, 1189, 118.78, 32.06, '孝宗即位', '宋孝宗即位 · 乾道、淳熙之治', '宋孝宗赵昚即位，为岳飞平反，起用张浚发动隆兴北伐。在内政上励精图治，史称南宋治世「乾淳之治」。', '为岳飞平反昭雪，清算秦桧党羽，大快人心；「乾淳之治」让南宋迎来难得的安定繁荣，朱熹理学也于此间蔚然成风。', 'era'),
  ('song', 1206, 1208, 118.78, 32.06, '开禧北伐', '开禧北伐', '权相韩侂胄主持北伐，因准备不足、将领不和而惨败。次年韩侂胄被杀，函首送金，宋增岁币、改称「伯侄之国」。', '北伐惨败使南宋国威扫地、军备消耗殆尽；韩侂胄函首送金之辱，令南宋对金关系从「叔侄」进一步降到「伯侄」，苟安之局愈发被动。', 'military'),
  ('song', 1206, 1227, 111, 43, '蒙古崛起', '成吉思汗建立大蒙古国', '铁木真在斡难河源召开忽里勒台，被推为「成吉思汗」，建立大蒙古国，随即开始对外征服。', '人类历史上疆域最辽阔的帝国由此开端；蒙古铁骑先后扫灭西辽、西夏、金与南宋，成为最终埋葬赵宋王朝的直接力量。', 'military'),
  ('song', 1234, 1245, 114.9, 33, '联蒙灭金', '宋蒙联军灭金', '南宋与蒙古联军攻破蔡州，金哀宗自缢，金朝灭亡。宋蒙随即因「端平入洛」收复三京失败而交恶，战端开启。', '「唇亡齿寒」，金亡之后宋蒙直接接壤，再无缓冲；端平入洛失败成为宋蒙全面战争的导火索，南宋由此转入灭亡倒计时。', 'military'),
  ('song', 1258, 1270, 106.5, 29.5, '钓鱼城之战', '钓鱼城之战', '蒙哥汗亲征南宋，围攻合州钓鱼城五个月不克，蒙哥本人重伤身亡（一说病故）。蒙古西征因此中止，世界历史为之改变。', '蒙哥汗战死直接中止了蒙古第三次西征，欧亚历史进程为之改写；钓鱼城固守三十六年，被誉为「上帝折鞭之处」的战争奇迹。', 'military'),
  ('song', 1271, 1279, 116.4, 39.9, '元朝建立', '忽必烈建元', '忽必烈取《易经》「大哉乾元」之意，定国号为「大元」，建都大都（今北京）。元朝正式建立，继续对南宋的灭国之战。', '中国历史上第一个由少数民族建立的大一统王朝诞生；大都（北京）自此成为此后七百年中国的政治中心。', 'military'),
  ('song', 1279, 1279, 110.5, 20.2, '崖山海战', '崖山海战 · 南宋灭亡', '元将张弘范率军围攻崖山，宋军战船被焚。丞相陆秀夫背幼主赵昺投海殉国，从死者十余万，南宋灭亡，元朝统一全国。', '南宋覆灭，中国版图首次被北方游牧民族完整统一；「崖山之后无中国」的悲壮记忆，成为汉人士大夫数百年难以释怀的集体创伤。', 'military');
